function lineSvg(points, opts){
  opts=opts||{};
  if(!Array.isArray(points)||points.length<2) return {error:'至少 2 个点'};
  var pts=points.map(function(p,i){ if(typeof p==='number') return {x:i+1,y:p}; if(p&&typeof p==='object'&&'x'in p) return {x:+p.x,y:+p.y}; if(Array.isArray(p)) return {x:+p[0],y:+p[1]}; return {x:+p[0],y:+p[1]}; });
  for(var i=0;i<pts.length;i++){ if(isNaN(pts[i].x)||isNaN(pts[i].y)) return {error:'点须为数字'}; }
  var xs=pts.map(function(p){return p.x;}), ys=pts.map(function(p){return p.y;});
  var xmin=Math.min.apply(null,xs), xmax=Math.max.apply(null,xs), ymin=Math.min.apply(null,ys), ymax=Math.max.apply(null,ys);
  if(xmin===xmax) xmax=xmin+1; if(ymin===ymax) ymax=ymin+1;
  var pad=24, W=200,H=140, pw=W-pad*2, ph=H-pad*2;
  function sx(x){ return pad + (x-xmin)/(xmax-xmin)*pw; }
  function sy(y){ return pad + ph - (y-ymin)/(ymax-ymin)*ph; }
  var poly=pts.map(function(p){ return sx(p.x).toFixed(1)+','+sy(p.y).toFixed(1); }).join(' ');
  var dots=pts.map(function(p){ return '<circle cx="'+sx(p.x).toFixed(1)+'" cy="'+sy(p.y).toFixed(1)+'" r="2.5" fill="#5E6AD2"/>'; }).join('');
  var svg='<svg viewBox="0 0 '+W+' '+H+'" xmlns="http://www.w3.org/2000/svg">'+
    '<line x1="'+pad+'" y1="'+(H-pad)+'" x2="'+(W-pad)+'" y2="'+(H-pad)+'" stroke="#3A3B3E" stroke-width="1"/>'+
    '<line x1="'+pad+'" y1="'+pad+'" x2="'+pad+'" y2="'+(H-pad)+'" stroke="#3A3B3E" stroke-width="1"/>'+
    '<polyline points="'+poly+'" fill="none" stroke="#5E6AD2" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>'+
    dots+'</svg>';
  return {svg:svg, min:ymin, max:ymax};
}
var EXPORTS={lineSvg:lineSvg};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LineChartForgePure = EXPORTS; }
